import json, pathlib, shutil, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); root = pathlib.Path(tempfile.mkdtemp(prefix='fozzylang-namespaced-consts-')); (root / 'src/model').mkdir(parents=True, exist_ok=True); (root / 'fozzy.toml').write_text('[package]\nname="demo"\nversion="0.1.0"\n\n[[target.bin]]\nname="demo"\npath="src/main.fzy"\n', encoding='utf-8'); (root / 'src/model/mod.fzy').write_text('mod types;\n', encoding='utf-8'); (root / 'src/model/types.fzy').write_text(textwrap.dedent('''\
const PROJECT_KIND_UNKNOWN: i32 = 0
const PROJECT_KIND_JUCE: i32 = 1
const PROJECT_KIND_CMAKE: i32 = 2

fn project_kind_label(kind: i32) -> str {
    if kind == PROJECT_KIND_JUCE {
        return "juce"
    }
    if kind == PROJECT_KIND_CMAKE {
        return "cmake"
    }
    return "unknown"
}
'''), encoding='utf-8'); (root / 'src/main.fzy').write_text(textwrap.dedent('''\
mod model;

fn main() -> i32 {
    let label0 = model.types.project_kind_label(model.types.PROJECT_KIND_UNKNOWN)
    let label1 = model.types.project_kind_label(model.types.PROJECT_KIND_JUCE)
    let label2 = model.types.project_kind_label(model.types.PROJECT_KIND_CMAKE)
    if label0 == "unknown" && label1 == "juce" && label2 == "cmake" {
        return 0
    }
    return 41
}
'''), encoding='utf-8');
for backend in ('cranelift', 'llvm'):
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'run', str(root), '--backend', backend, '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == 0, (backend, proc.returncode, payload, proc.stderr)
    assert payload.get('exitCode') == 0, (backend, payload)
ir = json.loads(subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'emit-ir', str(root), '--json'], cwd=str(repo), capture_output=True, text=True, check=True).stdout.strip())['backendIr']
assert 'call i32 @model_types_project_kind_label(i32 1)' in ir, ir
assert 'call i32 @model_types_project_kind_label(i32 2)' in ir, ir
assert 'icmp eq i32 %v0, 1' in ir or 'icmp eq i32 %v2, 1' in ir, ir
assert 'icmp eq i32 %v2, 2' in ir or 'icmp eq i32 %v0, 2' in ir, ir
print('native-namespaced-const-resolution-ok')

